window.LD=window.LD||{};window.LD["party/p5"]={"id":"p5","name":"The White Quills","poss":"The White Quills'","members":["h7","h13"],"leader":"h7","morale":100,"disposition":"honorable","motto":"Fair is fair, even to goblins.","banner":{"c1":"#e8e8e8","c2":"#e8e8e8","emblem":"eye"},"loc":"bleakmarsh","loc_name":"Bleakmarsh","goal":{"text":"to earn 300 silver between them before the season ends","kind":"purse","done":74,"progress":"1,600 silver, past the 300 aimed for","missed":false,"crew":"The White Quills","party":"p5"},"vows":[{"text":"to keep the peace: never draw first on another hero","day":1,"state":"kept","ended":90,"through":true,"progress":"kept on day 30 of season 3","crew":"The White Quills","party":"p5"}],"doing":"last seen hunting in Bleakmarsh","progress":null,"today":["XP: Bramble +60.","Coin between them: -9 silver (rations 9).","Came away with 2 rations, a fish, a sprig of moonpetal, a trinket."],"fights_today":[],"why":null,"founded_day":2,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"horse_opinions","title":"My Horse Has Opinions","tone":"funny","meter":"6/8","bpm":117,"diff":2,"day":28,"night":null,"n":5,"by":null,"lead":{"id":"h13","name":"Bramble","skill":0.843}},"renown":242,"season":{"wins":9,"bosses":0,"floors":2,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":3},"career":{"wins":28,"bosses":0,"floors":9,"gold":0,"deaths":0,"fled":0,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":89,"arguments":8},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"ox_wagon","name":"Homeward","label":"ox wagon","seats":5,"haul":70,"comfort":0,"since":84,"desc":"Slow as a wedding, carries a house.","moves":true,"puller":{"kind":"ox","name":"Bertha","label":"ox","colour":"red","owner":null},"paid":[["Bramble",59]]},"pace_gap":0,"rels":[{"party":"p6","score":86},{"party":"p3","score":30},{"party":"p2","score":21},{"party":"p1","score":13}],"events":[{"id":"e86","day":2,"season":1,"sday":2,"kind":"party_formed","imp":4,"text":"Vex and Bramble shake on it over a campfire in the Ashveil Crypts: they are now The White Quills. (Honorable, by the look of them.)","heroes":["h7","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e387","day":11,"season":1,"sday":11,"kind":"argument","imp":4,"text":"Third time's the charm: Vex and Bramble stop speaking entirely. The White Quills now travel in two silences.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e681","day":20,"season":1,"sday":20,"kind":"delve_day","imp":1,"text":"The White Quills work floor 2 of Cragtooth Warren at a steady pace: 2 rooms (the coin-floored room, the gilded room).","heroes":["h7","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]}},{"id":"e682","day":20,"season":1,"sday":20,"kind":"delve_done","imp":3,"text":"The daylight is a shock after 6 days, and The White Quills come out into it shading every eye. They reached the deepest floor, disarmed 1 trap, put 41% of it on paper, cleared 10 rooms, turned up Gnasher, the king's tithe-box and the gilded room, split 63 silver on the way up and turned back because they were down to the last torch. No boss, but the place paid. Cragtooth Warren is picked clean (94%) now, with the league's pencil marks all over it.","heroes":["h7","h13"],"parties":["p5"],"loc":"cragtooth_warren","days":6,"bottom":true,"rooms":["Gnasher","the king's tithe-box"],"gold":63,"turn":"dark"},{"id":"e683","day":20,"season":1,"sday":20,"kind":"ability","imp":2,"text":"Vex balances the books on the way out of Cragtooth Warren. Everything accounted for, plus a healing potion nobody remembers buying.","heroes":["h7"],"parties":["p5"],"loc":"cragtooth_warren","skill":"inventory_day","sk":"Inventory Day","rule":true},{"id":"e747","day":21,"season":1,"sday":21,"kind":"goal_done","imp":4,"text":"The White Quills can cross it off: earn 200 silver between them before the season ends. Drinks are on them. XP: Vex +919 (level 12!), Bramble +960 (level 12!).","heroes":["h7","h13"],"parties":["p5"],"xp":{"h7":919,"h13":960}},{"id":"e778","day":22,"season":1,"sday":22,"kind":"boss_race","imp":3,"text":"The White Quills and Cobalt Mercy are headed for the same hole in the ground: Thornmere Ruins, where Mother Thornmere waits. Somebody is going to be disappointed.","heroes":["h7","h13","h19","h20"],"parties":["p5","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e845","day":24,"season":1,"sday":24,"kind":"meet","imp":2,"text":"The White Quills and Cobalt Mercy share a fire in Thornmere Ruins. There is a short argument about the best road to Thornwall.","heroes":["h7","h13","h19","h20"],"parties":["p5","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e856","day":25,"season":1,"sday":25,"kind":"delve","imp":1,"text":"The White Quills descend into Thornmere Ruins, mostly unexplored (10%).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e857","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"The White Quills work floor 1 of Thornmere Ruins at a push pace: 2 rooms (the chandlery, a sealed space off the chandlery).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e858","day":25,"season":1,"sday":25,"kind":"night","imp":2,"text":"Vex tells a ghost story by the fire on floor 1 of Thornmere Ruins. Bramble sleeps with a hand on their weapon.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e893","day":26,"season":1,"sday":26,"kind":"fight","imp":1,"text":"In the sunken stair behind the font on floor 1 of Thornmere Ruins, a Will-o'-Wisp and a Swamp Troll get in the White Quills' way, briefly. The will-o'-wisp had been trouble right up until Vex's Fire Arrow. Bramble's Briar Line turned the fight. Loot: 27 silver each, 3 bottled wisplight, 3 troll hide.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f61","foes":["wisp","swamp_troll"],"where":"in the sunken stair behind the font on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-15,"wx":"fog"},{"id":"e894","day":26,"season":1,"sday":26,"kind":"delve_day","imp":1,"text":"The White Quills work floor 1 of Thornmere Ruins at a push pace: 3 rooms (the temple fish ponds, the sunken stair behind the font, the flooded side aisle).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e895","day":26,"season":1,"sday":26,"kind":"talent","imp":2,"text":"Vex brings back a brace of rabbits and quietly gives Bramble the best one. Game Hunter: a ranger's patience, mostly.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"game_hunter","wx":"fog"},{"id":"e925","day":26,"season":1,"sday":26,"kind":"argument","imp":2,"text":"Bramble and Vex spend supper disagreeing about whether the last fight was a retreat or a 'tactical repositioning', politely at first.","heroes":["h13","h7"],"parties":["p5"]},{"id":"e940","day":27,"season":1,"sday":27,"kind":"fight","imp":3,"text":"Bramble takes the worst of it as the White Quills see off 2 Will-o'-Wisps and a Bog Crawler in the tithe barn on floor 2 of Thornmere Ruins. The last will-o'-wisp decides enough is enough, and goes. Bramble's Briar Line took the strength out of the will-o'-wisp. Loot: 3 bottled wisplight, 3 wisp sugar, 6 chitin.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f64","foes":["wisp","wisp","bog_crawler"],"where":"in the tithe barn on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-62,"wx":"fog"},{"id":"e941","day":27,"season":1,"sday":27,"kind":"delve_day","imp":1,"text":"The White Quills work floor 2 of Thornmere Ruins at a push pace: 3 rooms (the tithe barn, the reliquary niche, the illuminators' desks).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e952","day":27,"season":1,"sday":27,"kind":"campfire","imp":1,"text":"Bramble laughs at one of Vex's jokes, then looks annoyed about it.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e954","day":28,"season":1,"sday":28,"kind":"delve_day","imp":1,"text":"The White Quills work floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the pipe organ, the physic garden).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e977","day":28,"season":1,"sday":28,"kind":"talent","imp":1,"text":"Bramble finds a defensible alcove at Thornmere Ruins for a rest: one door, high ceiling, no bones.","heroes":["h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"campsite_scout","wx":"fog"},{"id":"e979","day":28,"season":1,"sday":28,"kind":"music","imp":2,"text":"Somewhere on the road \"My Horse Has Opinions\" became The White Quills' song. Nobody voted. Nobody needed to.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","anthem":"horse_opinions","night":"n49","wx":"fog"},{"id":"e983","day":28,"season":1,"sday":28,"kind":"argument","imp":3,"text":"It starts with whose turn it was to keep watch. It ends with Vex and Bramble sleeping on opposite sides of the fire.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e990","day":29,"season":1,"sday":29,"kind":"delve_day","imp":1,"text":"The White Quills work floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the black pool, the chapel of the first abbot).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e991","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Vex lies back and names constellations for Bramble. Some of them are even real.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"stargazer","wx":"fog"},{"id":"e1020","day":30,"season":1,"sday":30,"kind":"wild_room","imp":3,"text":"Pip the Unstoppable Lutist was stopped, briefly, by Vex. Pip (record 0-1) says the cave did most of it.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","room":"wild_pip_underground","wx":"fog"},{"id":"e1021","day":30,"season":1,"sday":30,"kind":"delve_day","imp":1,"text":"The White Quills work floor 3 of Thornmere Ruins at a steady pace: 2 rooms (the singing chapel, the priests' cells).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":["wild_pip_underground"]},"wx":"fog"},{"id":"e1031","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Bramble finds a pale mushroom in a cave and decides, sensibly, not to eat it. Chalk it up to Off the Beaten Path.","heroes":["h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"off_the_beaten_path","wx":"fog"},{"id":"e1037","day":30,"season":1,"sday":30,"kind":"campfire","imp":1,"text":"Vex and Bramble end up on the same rope across a stream and have to trust each other for a minute.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1041","day":30,"season":1,"sday":30,"kind":"delve_done","imp":3,"text":"The White Quills climb out at last, 6 days older and a good deal dirtier. They got all the way to the bottom, found a sealed space off the chandlery, the sunken stair behind the font and the pipe organ, mapped 23% of it, took 14 rooms off the map's blank side and split 93 silver on the way up. Thornmere Ruins now stands partly explored (54%), every crew's chalk marks counted.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","days":6,"bottom":true,"rooms":["a sealed space off the chandlery","the sunken stair behind the font"],"gold":93,"wx":"fog"},{"id":"e1042","day":30,"season":1,"sday":30,"kind":"ability","imp":2,"text":"Vex goes through the haul from Thornmere Ruins line by line and finds a healing potion hiding under a goblin's hat.","heroes":["h7"],"parties":["p5"],"loc":"thornmere_ruins","skill":"inventory_day","sk":"Inventory Day","rule":true,"wx":"fog"},{"id":"e1090","day":31,"season":2,"sday":1,"kind":"ability","imp":1,"text":"Bramble spots a sprig of moonpetal growing in a ditch outside Bleakmarsh that every other traveller has trodden past.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true,"wx":"fog"},{"id":"e1135","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"A month in The White Quills: Vex could pick Bramble's footsteps out of a crowd now.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1142","day":33,"season":2,"sday":3,"kind":"delve","imp":1,"text":"The White Quills descend into Thornmere Ruins, partly explored (54%).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1143","day":33,"season":2,"sday":3,"kind":"fight","imp":1,"text":"Two Will-o'-Wisps and a Bog Crawler fall to the White Quills in the drowned nave on floor 1 of Thornmere Ruins. Vex drew, held, and let Fire Arrow go. The will-o'-wisp never saw it. Bramble's Briar Line turned the fight. Loot: 3 chitin, 3 wisp sugar.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f71","foes":["wisp","bog_crawler","wisp"],"where":"in the drowned nave on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-2},{"id":"e1144","day":33,"season":2,"sday":3,"kind":"delve_day","imp":1,"text":"The White Quills work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the wellhead, the drowned nave).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1174","day":34,"season":2,"sday":4,"kind":"delve_done","imp":1,"text":"The White Quills climb the last ladder after 2 days, and the sitting down happens at the top of it. They took 2 rooms off the map's blank side, got down to floor 1 and turned back because they were down to the last torch.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"dark"},{"id":"e1221","day":35,"season":2,"sday":5,"kind":"talent","imp":1,"text":"Bramble hacks a new path through the brambles near Bleakmarsh and saves the crew half a day.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"trailblazer"},{"id":"e1247","day":36,"season":2,"sday":6,"kind":"road","imp":3,"text":"The Muddy Boot Pack give Bramble a very old spoon, taken from a shrine nobody remembers. It is the highest honour the Pack has.","heroes":["h13","h7"],"parties":["p5"],"road":"ashfen~bleakmarsh","traveller":"muddy_boot","road_rec":"r255"},{"id":"e1303","day":37,"season":2,"sday":7,"kind":"ability","imp":2,"text":"Bramble follows a bee off the road near Bleakmarsh, through a gap in a wall, to a garden nobody has tended in years. They come back with a sprig of moonpetal and a head full of old gardening.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true},{"id":"e1311","day":37,"season":2,"sday":7,"kind":"ledger","imp":2,"text":"THE LEDGER: 9 hauls sold this week, 495 silver in all. Biggest haul: Wren, 154 silver in Frosthold. Back up from the deep: The White Quills (2 days in Thornmere Ruins), Tobias (2 days in the Wolf Den).","heroes":["h20","h7","h6"],"parties":["p5"]},{"id":"e1343","day":38,"season":2,"sday":8,"kind":"party_life","imp":1,"text":"Bramble asks Vex if the view is nice up there. It is.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e1344","day":38,"season":2,"sday":8,"kind":"night","imp":2,"text":"Bramble tells a ghost story by the fire in Thornmere Ruins. Vex insists on keeping the fire going until dawn. For warmth.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1349","day":38,"season":2,"sday":8,"kind":"boss_race","imp":3,"text":"Mother Thornmere has visitors coming. The Gravediggers of Ironhaven and The White Quills are both on the way to Thornmere Ruins, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h7","h13"],"parties":["p2","p5"],"loc":"thornmere_ruins"},{"id":"e1386","day":39,"season":2,"sday":9,"kind":"delve","imp":1,"text":"The White Quills descend into Thornmere Ruins, partly explored (57%).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1387","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The White Quills work floor 1 of Thornmere Ruins at a cautious pace: 1 room (the abbot's lodging).","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":1,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1405","day":39,"season":2,"sday":9,"kind":"campfire","imp":1,"text":"Bramble notices Vex has the same boots, a size bigger. Neither knows what to do with this.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1426","day":40,"season":2,"sday":10,"kind":"delve_done","imp":1,"text":"Thornmere Ruins hands The White Quills back after 2 days, dusty and squinting. They made it to floor 1, took 1 room off the map's blank side and turned back because they were down to the last torch.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"dark"},{"id":"e1427","day":40,"season":2,"sday":10,"kind":"ability","imp":2,"text":"After Thornmere Ruins, Vex makes everyone empty their packs onto a blanket and counts. There's a healing potion in the bottom of Bramble's bag. Everyone relaxes.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"inventory_day","sk":"Inventory Day","rule":true},{"id":"e1429","day":40,"season":2,"sday":10,"kind":"boss_race","imp":2,"text":"The race for Mother Thornmere is one crew lighter: The White Quills turned for other work. That leaves The Gravediggers of Ironhaven.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins"},{"id":"e1431","day":40,"season":2,"sday":10,"kind":"meet","imp":2,"text":"The White Quills and The Gravediggers of Ironhaven share a fire in Thornmere Ruins. Bramble shares directions.","heroes":["h7","h13","h8","h15","h2","h11"],"parties":["p5","p2"],"loc":"thornmere_ruins"},{"id":"e1449","day":41,"season":2,"sday":11,"kind":"party_life","imp":3,"text":"Bramble arrives at camp an hour behind Vex and finds the good spot by the fire taken.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1474","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The White Quills set their sights for the season: to see the world: 6 different places before the season ends.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e1515","day":42,"season":2,"sday":12,"kind":"campfire","imp":3,"text":"Vex and Bramble share the last of the bread without discussing it.","heroes":["h7","h13"],"parties":["p5"],"loc":"ashfen","wx":"storm"},{"id":"e1578","day":44,"season":2,"sday":14,"kind":"road","imp":3,"text":"Vex agrees to try the Doctor's famous tonic. It is mostly honey and fear, and does her no harm whatever.","heroes":["h7","h13"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"loom","road_rec":"r307"},{"id":"e1585","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"Vex audits a Thornwall trader's scales and finds them a little light. The trader pays up. Inventory Day: one of the things Vex learned the long way round.","heroes":["h7"],"parties":["p5"],"loc":"thornwall","skill":"inventory_day"},{"id":"e1595","day":44,"season":2,"sday":14,"kind":"goal_progress","imp":2,"text":"The White Quills are getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h7","h13"],"parties":["p5"]},{"id":"e1597","day":44,"season":2,"sday":14,"kind":"ledger","imp":2,"text":"Counters and coin this week: 25 sales, 1,906 silver changing hands. Biggest haul: Morwen, 206 silver in Ironhaven. Back up from the deep: The White Quills (2 days in Thornmere Ruins), Fenwick (4 days in Goblin Camp).","heroes":["h5","h7","h17"],"parties":["p5"]},{"id":"e1620","day":45,"season":2,"sday":15,"kind":"campfire","imp":2,"text":"Vex and Bramble discover a shared dislike of turnips. It is enough to be going on with.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad"},{"id":"e1634","day":46,"season":2,"sday":16,"kind":"night","imp":1,"text":"Something sings in the dark on the King's Road. Bramble goes to look and comes back with a trinket and a very quiet manner.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad"},{"id":"e1655","day":46,"season":2,"sday":16,"kind":"campfire","imp":1,"text":"Vex asks Bramble for directions, gets bad ones, and follows them anyway to be polite.","heroes":["h13","h7"],"parties":["p5"],"loc":"kingsroad"},{"id":"e1686","day":47,"season":2,"sday":17,"kind":"fight","imp":1,"text":"On the King's Road, the White Quills square up to a Bandit and carry the day. The fight was over the moment Bramble's Thorn Whip landed on the bandit. Loot: 8 silver each, 1 bag of stolen goods, a string of bandit sausages.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f108","foes":["bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"place","reworded":-25},{"id":"e1695","day":47,"season":2,"sday":17,"kind":"talent","imp":2,"text":"Vex finds a perfectly good roll of bandages in a ditch near the King's Road. She decides not to ask why. Scavenger, the guild calls it.","heroes":["h7"],"parties":["p5"],"loc":"kingsroad","skill":"scavenger"},{"id":"e1704","day":48,"season":2,"sday":18,"kind":"fight","imp":1,"text":"With Bramble taking the worst of it, the White Quills dispatch a Bandit Archer and a Bandit on the King's Road. Vex's Fire Arrow put the bandit archer down. Bramble kept them off everyone with Briar Line. Loot: 13 silver each, 1 bag of stolen goods.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f110","foes":["bandit_archer","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"hero","reworded":-37},{"id":"e1787","day":50,"season":2,"sday":20,"kind":"goal_done","imp":4,"text":"GOAL: The White Quills set out to see the world: 6 different places before the season ends, and they have done it, with 10 days to spare. It was Vex's idea in the first place. XP: Vex +1080 (level 16!), Bramble +960 (level 16!).","heroes":["h7","h13"],"parties":["p5"],"xp":{"h7":1080,"h13":960}},{"id":"e1809","day":51,"season":2,"sday":21,"kind":"ability","imp":2,"text":"Near Redcrag Hills, Bramble wades into a bog any sensible traveller walks round. They come out muddy to the waist with a sprig of moonpetal and a new understanding of bogs.","heroes":["h13"],"parties":["p5"],"loc":"redcrag","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true,"wx":"fog"},{"id":"e1817","day":51,"season":2,"sday":21,"kind":"campfire","imp":1,"text":"Vex learns Bramble can't swim and promises not to tell. It's the first promise between them.","heroes":["h7","h13"],"parties":["p5"],"loc":"redcrag","wx":"fog"},{"id":"e1826","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"The White Quills dispatch a Giant Bat and a Cave Troll in Redcrag Hills. Bramble put Thorn Whip into the cave troll to end it, and lowered the bow. Loot: 12 silver each, 3 troll haunches.","heroes":["h7","h13"],"parties":["p5"],"loc":"redcrag","fight":"f121","foes":["giant_bat","cave_troll"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"plain","wx":"fog"},{"id":"e1861","day":53,"season":2,"sday":23,"kind":"fight","imp":2,"text":"Two Cave Trolls fall to the White Quills in Redcrag Hills. After Bramble's Briar Line, the cave troll hit like a tired farmhand. Loot: 17 silver each, 1 troll hide, 3 troll haunches.","heroes":["h7","h13"],"parties":["p5"],"loc":"redcrag","fight":"f130","foes":["cave_troll","cave_troll"],"where":"in Redcrag Hills","won":true,"close":true,"shape":"foe","reworded":-2,"wx":"fog"},{"id":"e1891","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Bramble finds a path nobody has used in years, and it's a lovely one.","heroes":["h13"],"parties":["p5"],"loc":"redcrag","skill":"off_the_beaten_path","wx":"fog"},{"id":"e1906","day":54,"season":2,"sday":24,"kind":"road","imp":4,"text":"A giant lies asleep across the road to Ironhaven, a hill with a beard. Every traveller queues to climb over the arm. Vex goes last and sits on a finger.","heroes":["h7","h13"],"parties":["p5"],"road":"ironhaven~redcrag","road_rec":"r369"},{"id":"e1986","day":56,"season":2,"sday":26,"kind":"road","imp":3,"text":"Vex is handed Jory Bellwether's handbell and asked to call the hour. The hour is not agreed upon, but the bell is a good one.","heroes":["h7","h13"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"jory","road_rec":"r392"},{"id":"e2000","day":56,"season":2,"sday":26,"kind":"campfire","imp":3,"text":"Lord Basking the lizard sniffs Vex all over and approves. Bramble takes the hint.","heroes":["h13","h7"],"parties":["p5"],"loc":"carrbridge"},{"id":"e2009","day":57,"season":2,"sday":27,"kind":"road","imp":3,"text":"Vex marks the strongbox and sends word to the nearest village. The owners' grandchildren are found, and are glad of the news.","heroes":["h7","h13"],"parties":["p5"],"road":"bleakmarsh~carrbridge","road_rec":"r394"},{"id":"e2019","day":57,"season":2,"sday":27,"kind":"ability","imp":2,"text":"Bramble ducks off the road near Bleakmarsh, wades a stream, climbs a bank and comes back with a sprig of moonpetal. And a story about the stream.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true},{"id":"e2029","day":57,"season":2,"sday":27,"kind":"campfire","imp":2,"text":"Vex and Bramble both reach for the same stool at the campfire. Vex lets Bramble have it, this once.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2038","day":58,"season":2,"sday":28,"kind":"fight","imp":1,"text":"With Bramble hitting hardest, the White Quills cut down a Giant Spider in Bleakmarsh. Bramble's last Thorn Whip settled it. Vex landed the hit that turned it, then went straight back to guarding the packs. Loot: 4 spider legs.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f138","foes":["giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e2039","day":58,"season":2,"sday":28,"kind":"fight","imp":2,"text":"In Bleakmarsh, 2 Giant Spiders and a Bog Crawler get in the White Quills' way, briefly. The last giant spider doesn't stay to see the end. Vex's Fire Arrow found the giant spider from the back row. Bramble's High Ground turned the fight. Loot: a giant spider leg.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f139","foes":["bog_crawler","giant_spider","giant_spider"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-37},{"id":"e2074","day":59,"season":2,"sday":29,"kind":"fight","imp":1,"text":"Back in Bleakmarsh, the White Quills dispatch a Bog Crawler. Bramble's Thorn Whip was where the fight changed hands. Vex never once gave ground. Loot: 6 chitin, 3 bog crawler claws.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f141","foes":["bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"again","reworded":-6},{"id":"e2075","day":59,"season":2,"sday":29,"kind":"fight","imp":1,"text":"The White Quills, in fine spirits lately, make short work of a Bog Crawler in Bleakmarsh. Vex ended it with Fire Arrow. Bramble kept them off everyone with High Ground. Loot: 3 chitin, 3 bog crawler claws.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f142","foes":["bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2194","day":62,"season":3,"sday":2,"kind":"ability","imp":2,"text":"Bramble spots a sprig of moonpetal growing in a ditch outside Bleakmarsh that every other traveller has trodden past.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true},{"id":"e2205","day":63,"season":3,"sday":3,"kind":"fight","imp":1,"text":"The White Quills cut down a Will-o'-Wisp in Bleakmarsh, in thick fog. The final blow was Bramble's Thorn Whip. Loot: 3 bottled wisplight.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f145","foes":["wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"weather","reworded":-14,"wx":"fog"},{"id":"e2234","day":64,"season":3,"sday":4,"kind":"meet","imp":2,"text":"Azure Edge runs into The White Quills in Bleakmarsh. Stories are exchanged, most of them exaggerated.","heroes":["h3","h9","h1","h5","h7","h13"],"parties":["p3","p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2235","day":64,"season":3,"sday":4,"kind":"gift","imp":2,"text":"Bramble gives Vex a Set of Dice Missing the Six. \"For luck,\" Bramble says, and won't explain further.","heroes":["h13","h7"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2247","day":65,"season":3,"sday":5,"kind":"fight","imp":1,"text":"The White Quills get the better of a Giant Spider and a Bog Crawler in Bleakmarsh. Bramble's Briar Line took the strength out of the bog crawler. Vex's Fire Arrow did the damage (2 times). Loot: 3 chitin, a giant spider leg.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f149","foes":["giant_spider","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-13,"wx":"fog"},{"id":"e2248","day":65,"season":3,"sday":5,"kind":"night","imp":2,"text":"A grey dwarf shares The White Quills' fire in Bleakmarsh and swears on his beard there's a room in the Ashveil Crypts nobody has opened. There isn't much beard left.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2262","day":65,"season":3,"sday":5,"kind":"gift","imp":2,"text":"Bramble admired Vex's Clay Pipe, Never Lit one too many times. Now it's Bramble's.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2263","day":65,"season":3,"sday":5,"kind":"talent","imp":2,"text":"A farmer near Bleakmarsh recognises Bramble from a fox trap that's still working, and presses a dozen eggs on them.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"trap_seller","wx":"fog"},{"id":"e2274","day":66,"season":3,"sday":6,"kind":"road","imp":3,"text":"Vex climbs the deck of a ship that sits in a meadow near the road to Carrbridge, and finds the captain's tea still warm.","heroes":["h7","h13"],"parties":["p5"],"road":"bleakmarsh~carrbridge","road_rec":"r458"},{"id":"e2330","day":67,"season":3,"sday":7,"kind":"gift","imp":2,"text":"Vex gives Bramble a Medal of Baked Crust. \"For luck,\" Vex says, and won't explain further.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e2360","day":68,"season":3,"sday":8,"kind":"road","imp":3,"text":"Bramble sits by the circus fire while Cinder Marsh swallows a torch for a lesson, and then tries it with a cold one. It is harder than it looks.","heroes":["h13","h7"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"mumchance","road_rec":"r463"},{"id":"e2435","day":70,"season":3,"sday":10,"kind":"road","imp":2,"text":"Vex backs a fish at the Lakeside Lamprey against a grumpy old angler, and pockets 2 silver when the fish is bigger.","heroes":["h7","h13"],"parties":["p5"],"road":"kingsroad~thornwall","road_rec":"r472"},{"id":"e2455","day":71,"season":3,"sday":11,"kind":"fight","imp":1,"text":"With Vex hitting hardest, the White Quills make short work of a Bandit Captain and a Bandit on the King's Road. Vex's Fire Arrow set the bandit captain alight. Bramble's Thorn Whip did the damage (2 times). Loot: 32 silver each, 10 stolen goods, 4 bandit sausages.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f171","foes":["bandit_captain","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"hero","reworded":-26},{"id":"e2478","day":71,"season":3,"sday":11,"kind":"campfire","imp":2,"text":"Vex and Bramble discover they grew up three valleys apart. The conversation lasts longer than either expected.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad"},{"id":"e2485","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The White Quills set their sights for the season: to earn 300 silver between them before the season ends.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e2502","day":72,"season":3,"sday":12,"kind":"fight","imp":1,"text":"On the King's Road, the White Quills beat a Bandit Captain and a Wolf. Two fights at once: the bandits and the wolves were already at each other's throats when The White Quills walked into the middle of it. The last wolf doesn't stay to see the end. Bramble's Thorn Whip put poison in the bandit captain, and it did its slow work. Loot: 28 silver each, 10 stolen goods.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f172","foes":["bandit_captain","wolf"],"where":"in The King's Road","won":true,"close":false,"shape":"place","reworded":-23},{"id":"e2517","day":72,"season":3,"sday":12,"kind":"ability","imp":2,"text":"Bramble follows a bee off the road near the King's Road, through a gap in a wall, to a garden nobody has tended in years. They come back with a sprig of moonpetal and a head full of old gardening.","heroes":["h13"],"parties":["p5"],"loc":"kingsroad","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true},{"id":"e2537","day":73,"season":3,"sday":13,"kind":"fight","imp":2,"text":"The White Quills, in fine spirits lately, cut down 2 Bandit Captains and a Bandit on the King's Road. Bramble's Briar Line took the strength out of the bandit captain. Loot: 88 silver each, 10 stolen goods, 1 gem.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f176","foes":["bandit_captain","bandit_captain","bandit"],"where":"in The King's Road","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2552","day":73,"season":3,"sday":13,"kind":"goal_progress","imp":2,"text":"The White Quills are getting close: earn 300 silver between them before the season ends (232 of 300 silver).","heroes":["h7","h13"],"parties":["p5"]},{"id":"e2579","day":74,"season":3,"sday":14,"kind":"goal_done","imp":4,"text":"GOAL: The White Quills set out to earn 300 silver between them before the season ends, and they have done it, with 16 days to spare. XP: Vex +1104 (level 19!), Bramble +960 (level 19!).","heroes":["h7","h13"],"parties":["p5"],"xp":{"h7":1104,"h13":960}},{"id":"e2590","day":75,"season":3,"sday":15,"kind":"trade","imp":2,"text":"The White Quills buy 25 healing potions in Carrbridge, betting on better prices in Thornwall.","heroes":["h7","h13"],"parties":["p5"],"loc":"carrbridge"},{"id":"e2626","day":76,"season":3,"sday":16,"kind":"road","imp":3,"text":"Ma Mumchance asks Bramble, quite seriously, whether they would care to join the circus as the Human Cannonball. Bramble says no, politely, and is given a free sausage.","heroes":["h13","h7"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"mumchance","road_rec":"r507"},{"id":"e2658","day":76,"season":3,"sday":16,"kind":"argument","imp":2,"text":"Vex says one thing too many about the party's name. Bramble says two.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e2682","day":77,"season":3,"sday":17,"kind":"road","imp":4,"text":"Lark tells Vex at last what is in the satchel: letters, only letters, hundreds of them between people who miss each other.","heroes":["h7","h13"],"parties":["p5"],"road":"ashfen~carrbridge","traveller":"lark","road_rec":"r524"},{"id":"e2688","day":77,"season":3,"sday":17,"kind":"talent","imp":1,"text":"Vex has a book open next to her ale at the Ashfen tavern and is underlining things. Nobody interrupts. Studious: one of the things Vex learned the long way round.","heroes":["h7"],"parties":["p5"],"loc":"ashfen","skill":"study","wx":"fog"},{"id":"e2695","day":77,"season":3,"sday":17,"kind":"argument","imp":1,"text":"The White Quills spend the evening listening to Vex and Bramble argue about whether the last fight was a retreat or a 'tactical repositioning'.","heroes":["h7","h13"],"parties":["p5"]},{"id":"e2719","day":78,"season":3,"sday":18,"kind":"road","imp":2,"text":"Bramble walks up on Brother Aldo for the first time reading a map of shrines upside down, and not minding in the least.","heroes":["h13","h7"],"parties":["p5"],"road":"ashfen~ashveil_crypts","traveller":"aldo","road_rec":"r531"},{"id":"e2743","day":79,"season":3,"sday":19,"kind":"delve","imp":1,"text":"The White Quills descend into the Ashveil Crypts, partly explored (46%).","heroes":["h7","h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e2744","day":79,"season":3,"sday":19,"kind":"night","imp":2,"text":"Bramble's ghost story on floor 2 of the Ashveil Crypts ends with \"...and it was standing right behind them.\" Vex does not look behind her once, all night.","heroes":["h7","h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e2782","day":80,"season":3,"sday":20,"kind":"delve_done","imp":1,"text":"The White Quills come out after 2 days, and the first thing anyone wants is bread. They made it to floor 2 and turned back because they were down to the last torch.","heroes":["h7","h13"],"parties":["p5"],"loc":"ashveil_crypts","days":2,"bottom":false,"rooms":[],"gold":0,"turn":"dark"},{"id":"e2783","day":80,"season":3,"sday":20,"kind":"ability","imp":2,"text":"Vex goes through the haul from the Ashveil Crypts line by line and finds a healing potion hiding under a goblin's hat.","heroes":["h7"],"parties":["p5"],"loc":"ashveil_crypts","skill":"inventory_day","sk":"Inventory Day","rule":true},{"id":"e2784","day":80,"season":3,"sday":20,"kind":"gift","imp":2,"text":"By the fire, Bramble quietly hands Vex a Goblin's Lucky Spoon. Vex pockets it like it's treasure.","heroes":["h13","h7"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e2791","day":80,"season":3,"sday":20,"kind":"talent","imp":2,"text":"Bramble presses a flower in their journal. The journal is mostly flowers now.","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts","skill":"off_the_beaten_path"},{"id":"e2797","day":81,"season":3,"sday":21,"kind":"road","imp":4,"text":"Brother Aldo reaches his last shrine and reads the walkers' names aloud to the empty hills. One of them is Bramble's.","heroes":["h13","h7"],"parties":["p5"],"road":"ashfen~ashveil_crypts","traveller":"aldo","road_rec":"r544"},{"id":"e2821","day":81,"season":3,"sday":21,"kind":"meet","imp":2,"text":"The Lantern of Carrbridge runs into The White Quills on the road between Ashfen and the Ashveil Crypts. Stories are exchanged, most of them exaggerated.","heroes":["h4","h18","h12","h7","h13"],"parties":["p1","p5"],"loc":"ashfen"},{"id":"e2824","day":81,"season":3,"sday":21,"kind":"campfire","imp":1,"text":"Bramble asks Vex how Wayfinders and Treasure Hunters are supposed to work together. Neither knows. They work it out.","heroes":["h13","h7"],"parties":["p5"],"loc":"ashfen"},{"id":"e2829","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"THE LEDGER: 26 hauls sold this week, 1,976 silver in all. Biggest haul: Barnaby, 234 silver in Veldrock. Back up from the deep: Azure Edge (2 days in Frostspire), The White Quills (2 days in the Ashveil Crypts), The Gravediggers of Ironhaven (2 days in Emberdeep).","heroes":["h19","h3","h7","h8"],"parties":["p3","p5","p2"]},{"id":"e2845","day":82,"season":3,"sday":22,"kind":"ambush","imp":2,"text":"Vex takes the worst of it as the White Quills dispatch 2 Bandit Archers and a Bandit Captain on the road to Carrbridge. The last bandit archer takes off and isn't seen again. It was Bramble's Thorn Whip that dropped the bandit archer. Vex saw every rush coming and shouted it in time. Loot: 43 silver each, 6 bandit sausages, 7 stolen goods.","heroes":["h7","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f192","foes":["bandit_archer","bandit_archer","bandit_captain"],"where":"on the road to Carrbridge","won":true,"close":false,"shape":"hero","reworded":-54},{"id":"e2918","day":84,"season":3,"sday":24,"kind":"wagon","imp":3,"text":"The White Quills chip in 59 silver for an ox wagon in Thornwall and name it Homeward. Bramble paid for all of it.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e2931","day":84,"season":3,"sday":24,"kind":"campfire","imp":2,"text":"Vex shows Bramble a scar and Bramble shows one back. They compare, warily.","heroes":["h7","h13"],"parties":["p5"],"loc":"greenwood"},{"id":"e2957","day":85,"season":3,"sday":25,"kind":"fight","imp":1,"text":"The White Quills get the better of a Wolf in the Greenwood. Vex ended it with Fire Arrow.","heroes":["h7","h13"],"parties":["p5"],"loc":"greenwood","fight":"f204","foes":["wolf"],"where":"in The Greenwood","won":true,"close":false,"shape":"plain","reworded":-11},{"id":"e2972","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Vex reads the party's ledger aloud by firelight. It is somehow soothing.","heroes":["h7"],"parties":["p5"],"loc":"greenwood","skill":"inventory_day"},{"id":"e2973","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Vex offers Bramble the dry side of the tent. Bramble accepts, suspiciously.","heroes":["h7","h13"],"parties":["p5"],"loc":"greenwood"},{"id":"e2994","day":86,"season":3,"sday":26,"kind":"fight","imp":2,"text":"Back in the Greenwood, the White Quills see off 3 Giant Spiders. The last giant spider takes off and isn't seen again. Bramble's Thorn Whip went in deep, and the giant spider slowed down after that. Loot: 6 chitin, 6 spider legs.","heroes":["h7","h13"],"parties":["p5"],"loc":"greenwood","fight":"f206","foes":["giant_spider","giant_spider","giant_spider"],"where":"in The Greenwood","won":true,"close":false,"shape":"again","reworded":-31},{"id":"e3002","day":86,"season":3,"sday":26,"kind":"ability","imp":2,"text":"Bramble leaves the path near the Greenwood for an hour. Vex is about to send a search party when Bramble reappears with a sprig of moonpetal and muddy knees.","heroes":["h13","h7"],"parties":["p5"],"loc":"greenwood","skill":"off_the_beaten_path","sk":"Off the Beaten Path","rule":true},{"id":"e3008","day":86,"season":3,"sday":26,"kind":"argument","imp":2,"text":"Bramble and Vex of The White Quills have a shouting match about whose turn it was to keep watch.","heroes":["h13","h7"],"parties":["p5"]},{"id":"e3029","day":87,"season":3,"sday":27,"kind":"ambush","imp":2,"text":"It's a Giant Spider against the White Quills on the road to Thornwall, and it isn't close. Vex closed it out with Fire Arrow on the giant spider. Bramble kept them off everyone with High Ground. Loot: 1 chitin.","heroes":["h7","h13"],"parties":["p5"],"loc":"greenwood","fight":"f209","foes":["giant_spider"],"where":"on the road to Thornwall","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e3030","day":87,"season":3,"sday":27,"kind":"road","imp":2,"text":"Bramble wedges a spare paddle into the Millpond Arms wheel when it jams, and Odo Baskerly cheers as the water takes it round again.","heroes":["h13","h7"],"parties":["p5"],"road":"greenwood~thornwall","road_rec":"r587"},{"id":"e3041","day":87,"season":3,"sday":27,"kind":"meet","imp":2,"text":"The White Quills and Azure Edge pass on the road between the Greenwood and Thornwall. There is a short argument about the best road to Carrbridge.","heroes":["h7","h13","h3","h9","h1","h5"],"parties":["p5","p3"],"loc":"greenwood"},{"id":"e3058","day":88,"season":3,"sday":28,"kind":"raid","imp":5,"text":"Thornwall is attacked at dusk by yetis out of Frostspire, and Vex and Bramble hold the gate. The town pays the defenders 25 silver each, and nobody in Thornwall will buy their own drink tonight.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornwall","fight":"f211","wx":"rain"},{"id":"e3059","day":88,"season":3,"sday":28,"kind":"song","imp":3,"text":"Listen out at The Sagging Beam for \"The Gate at Thornwall\". The tune is borrowed. The words are new.","heroes":["h7","h13"],"parties":["p5"],"loc":"thornwall","song":"s88_24","wx":"rain"},{"id":"e3127","day":90,"season":3,"sday":30,"kind":"talent","imp":1,"text":"Bramble lights the temple candle stub for exactly one minute, then pinches it out. It has to last.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e3128","day":90,"season":3,"sday":30,"kind":"night","imp":2,"text":"Something sings in the dark in Bleakmarsh. Bramble goes to look and comes back with a trinket and a very quiet manner.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e3149","day":90,"season":3,"sday":30,"kind":"ability","imp":2,"text":"Rain on the road, so Bramble forages under the hedges: sorrel, cobnuts and a damp but perfectly good sprig of moonpetal. Lunch is surprisingly cheerful.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"forest_larder","sk":"Forest Larder","rule":true},{"id":"e3153","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Vex draws an X on Bramble's hand while Bramble sleeps. 'For luck,' she explains.","heroes":["h7","h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"x_marks_the_spot"},{"id":"e3168","day":90,"season":3,"sday":30,"kind":"vow_kept","imp":4,"text":"VOWS KEPT TO THE END OF THE AGE: The Lantern of Carrbridge, to die rich (sworn in season 2); Azure Edge, never to pay a toll (sworn in season 1); The Tidal Almanac, never to retreat (sworn in season 2); The Tidal Almanac, to die rich (sworn in season 2); The White Quills, to keep the peace: never draw first on another hero (sworn in season 1); Cobalt Mercy, to die rich (sworn in season 2); Tobias, never to pay a toll (sworn in season 2); Juniper, never to retreat (sworn in season 1). Every one of them held.","heroes":["h10","h6"],"parties":["p1","p3","p4","p5","p6"]}],"roles":{"h13":"Tracker","h7":"Leader · Scout"},"quest":{"what":"Hunt","where":"Bleakmarsh","why":"foraging and hunting","floor":null,"floors":null},"tactics":{"front":[],"back":["h7","h13"],"plan":"Vex and Bramble pick off whatever gets close.","traits":{"boldness":0.05,"risk":-0.13,"greed":-0.2,"sociability":-0.41,"honor":0.68,"curiosity":0.5,"temper":-0.29,"loyalty":-0.34},"mix":"1 talker, 1 bow","notes":["Nobody wants the front row. Whoever's nearest takes the hits.","No healer: every wound comes home with them."],"style":["mixed"],"skills":[{"label":"Damage","skills":[{"hero":"h7","id":"fire_arrow","name":"Fire Arrow","desc":"Pitch, a spark, and a hopeful arc.","tags":["fire"],"rank":1,"uses":38},{"hero":"h13","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":33},{"hero":"h7","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h13","id":"briar_line","name":"Briar Line","desc":"Leads the enemy through the brambles. Then waits.","tags":["nature"],"rank":1,"uses":17},{"hero":"h13","id":"high_ground","name":"High Ground","desc":"Got the crew up the hill before the fight knew it was a fight.","tags":["nature","travel"],"rank":2,"uses":16},{"hero":"h13","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":1,"uses":4},{"hero":"h7","id":"grab_and_go","name":"Grab and Go","desc":"Has the map, the idol and a head start.","tags":["travel"],"rank":3,"uses":1}]},{"label":"Always on","skills":[{"hero":"h7","id":"shoulder_to_shoulder","name":"Shoulder to Shoulder","desc":"Stands close enough to share a shield.","tags":["command"],"rank":2,"uses":0},{"hero":"h7","id":"coin_shield","name":"Coin Shield","desc":"Buys the best armor. Obviously.","tags":["trade","guard"],"rank":2,"uses":0},{"hero":"h7","id":"trap_hop","name":"Trap Hop","desc":"Steps on exactly the flagstones that don't click.","tags":["travel"],"rank":1,"uses":0},{"hero":"h13","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":2,"uses":0},{"hero":"h13","id":"lay_of_the_land","name":"Lay of the Land","desc":"Fights on ground they walked yesterday.","tags":["nature","travel"],"rank":1,"uses":0},{"hero":"h13","id":"trail_sense","name":"Trail Sense","desc":"Never trips. Has never had to look down.","tags":["travel"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h7","id":"peacemaker","name":"Peacemaker","desc":"Stops the argument before it gets to the swords.","tags":["command","holy"],"rank":1,"uses":0},{"hero":"h7","id":"study","name":"Studious","desc":"Reads everything, learns faster.","tags":["lore"],"rank":2,"uses":0},{"hero":"h7","id":"scavenger","name":"Scavenger","desc":"Checks every pocket, every boot, every crevice.","tags":[],"rank":1,"uses":0},{"hero":"h7","id":"toll_talker","name":"Toll Talker","desc":"Has never paid a full toll. Has never been rude about it.","tags":["travel","trade"],"rank":1,"uses":0},{"hero":"h7","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h7","id":"game_hunter","name":"Game Hunter","desc":"Comes back from a short walk with dinner.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h7","id":"stargazer","name":"Stargazing","desc":"Can find north, the Swan, and the Little Ladle.","tags":["travel","lore"],"rank":1,"uses":0},{"hero":"h7","id":"camp_cook","name":"Camp Cook","desc":"Makes rations taste like dinner. Party morale up.","tags":[],"rank":1,"uses":0},{"hero":"h7","id":"pathfinding","name":"Pathfinding","desc":"Knows the back ways.","tags":["travel","nature"],"rank":1,"uses":0},{"hero":"h13","id":"trap_seller","name":"Trap Seller","desc":"Every farmer with a fox problem knows their name.","tags":["craft"],"rank":1,"uses":0},{"hero":"h13","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":3,"uses":0},{"hero":"h13","id":"campsite_scout","name":"Campsite Scout","desc":"Finds the flat spot. Every time.","tags":["travel","nature"],"rank":1,"uses":0},{"hero":"h13","id":"wanderlust","name":"Wanderlust","desc":"Every road teaches something.","tags":["travel"],"rank":2,"uses":0},{"hero":"h13","id":"trailblazer","name":"Trailblazer","desc":"Cuts a day off long roads.","tags":["travel"],"rank":1,"uses":0},{"hero":"h13","id":"tinkerer","name":"Tinkerer","desc":"Takes things apart. Usually puts them back.","tags":["craft","arcane"],"rank":1,"uses":0},{"hero":"h13","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":1,"uses":0}]}],"share":[{"hero":"h7","dmg":1603,"healed":0,"taken":250,"kills":9,"row":"back"},{"hero":"h13","dmg":1492,"healed":0,"taken":179,"kills":8,"row":"back"}],"ground":{"name":"The King's Road","fights":6}},"trophies":[]};